const listAllGroups = `-- name: ListAllGroups :many
SELECT g.org_id, g.id, g.issuer, g.display_name, g.external_id, g.created_at, g.updated_at, (SELECT count(*) FROM pc.group_members m WHERE m.org_id = g.org_id AND m.group_id = g.id)::bigint AS member_count
FROM pc.groups g
WHERE g.org_id = $1 AND g.id > coalesce($2::uuid, '00000000-0000-0000-0000-000000000000')
ORDER BY g.id
LIMIT $3
`

type ListAllGroupsRow struct {
	OrgID       ids.OrgID
	ID          ids.UUID
	Issuer      string
	DisplayName string
	ExternalID  *string
	CreatedAt   time.Time
	UpdatedAt   time.Time
	MemberCount int64
}

func (q *Queries) ListAllGroups(ctx context.Context, orgID ids.OrgID, after ids.UUID, pageLimit int32) ([]ListAllGroupsRow, error) {
	rows, err := q.db.Query(ctx, listAllGroups, orgID, after, pageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAllGroupsRow{}
	for rows.Next() {
		var i ListAllGroupsRow
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.Issuer,
			&i.DisplayName,
			&i.ExternalID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.MemberCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

